/**
 * audio.js - CFO Agent Audio Engine
 * Embeds the hermians-style ambient sound directly.
 * Uses Web Audio API for UI sound effects.
 */

// Embedded ambient audio (base64 m4a)
const AMBIENT_B64 = ''

class AudioEngine {
  constructor() {
    this.ctx        = null
    this.master     = null
    this.droneOn    = false
    this.muted      = false
    this._ready     = false
    this.ambientEl  = null
  }

  init() {
    if (this._ready) return
    try {
      this.ctx    = new (window.AudioContext || window.webkitAudioContext)()
      this.master = this.ctx.createGain()
      this.master.gain.value = 1
      this.master.connect(this.ctx.destination)
      this._ready = true
    } catch(e) {}
  }

  setMute(muted) {
    this.muted = muted
    if (this.master) {
      this.master.gain.setTargetAtTime(muted ? 0 : 1, this.ctx.currentTime, 0.1)
    }
    if (this.ambientEl) {
      this.ambientEl.muted = muted
    }
  }

  toggle() {
    this.setMute(!this.muted)
    return this.muted
  }

  startDrone() {
    if (this.droneOn) return
    this.droneOn = true
    try {
      // Use embedded audio file
      const dataUrl = 'data:audio/m4a;base64,' + AMBIENT_B64
      this.ambientEl = new Audio(dataUrl)
      this.ambientEl.loop   = true
      this.ambientEl.volume = 0
      this.ambientEl.muted  = this.muted
      this.ambientEl.play().catch(()=>{})
      // Fade in
      let vol = 0
      const fade = setInterval(() => {
        vol = Math.min(0.35, vol + 0.01)
        if (this.ambientEl) this.ambientEl.volume = vol
        if (vol >= 0.35) clearInterval(fade)
      }, 200)
    } catch(e) {
      // Fall back to synthetic drone
      this._syntheticDrone()
    }
  }

  stopDrone() {
    if (this.ambientEl) {
      this.ambientEl.pause()
      this.ambientEl = null
    }
    this.droneOn = false
  }

  _syntheticDrone() {
    if (!this._ready) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const g   = ctx.createGain()
    const f   = ctx.createBiquadFilter()
    f.type = 'lowpass'; f.frequency.value = 600
    g.gain.setValueAtTime(0, now)
    g.gain.linearRampToValueAtTime(0.08, now + 4)
    f.connect(g); g.connect(this.master)
    const freqs = [55, 110, 165]
    freqs.forEach(freq => {
      const o = ctx.createOscillator()
      o.type = 'sine'; o.frequency.value = freq
      o.connect(f); o.start(now)
    })
  }

  _beep(freq=880, dur=0.04, vol=0.06, type='square') {
    if (!this._ready) return
    try {
      const ctx = this.ctx, now = ctx.currentTime
      const o = ctx.createOscillator(), g = ctx.createGain()
      o.connect(g); g.connect(this.master)
      o.type = type; o.frequency.value = freq
      g.gain.setValueAtTime(vol, now)
      g.gain.exponentialRampToValueAtTime(0.001, now + dur)
      o.start(now); o.stop(now + dur)
    } catch(e) {}
  }

  // Hacker-style fast mechanical click
  key() {
    if (!this._ready) return
    this._beep(1200 + Math.random() * 800, 0.02, 0.03, 'square')
    if (Math.random() > 0.7) this._beep(400 + Math.random() * 200, 0.015, 0.02, 'sawtooth')
  }

  // Boot up sound - ascending tones
  boot() {
    if (!this._ready) return
    [220, 330, 440, 550, 660].forEach((f,i) =>
      setTimeout(() => this._beep(f, 0.08, 0.07, 'sine'), i * 60)
    )
  }

  // Each terminal line appearing
  line() {
    if (!this._ready) return
    const f = 400 + Math.random() * 400
    this._beep(f, 0.03, 0.04, 'square')
  }

  // Signal locked - descending chord
  lock() {
    if (!this._ready) return
    [1100, 880, 660, 440, 330].forEach((f,i) =>
      setTimeout(() => this._beep(f, 0.1, 0.07, 'sine'), i * 70)
    )
  }

  // Launch dashboard
  launch() {
    if (!this._ready) return
    [440, 554, 659, 880, 1100].forEach((f,i) =>
      setTimeout(() => this._beep(f, 0.12, 0.07, 'sine'), i * 55)
    )
  }

  // Execution sound - industrial
  exec() {
    if (!this._ready) return
    this._beep(180, 0.25, 0.08, 'sawtooth')
    setTimeout(() => this._beep(240, 0.15, 0.06, 'sawtooth'), 80)
  }

  // Success - rising tones
  done() {
    if (!this._ready) return
    [660, 880, 1100, 1320].forEach((f,i) =>
      setTimeout(() => this._beep(f, 0.12, 0.06, 'sine'), i * 90)
    )
  }

  // Deploy new contract
  deploy() {
    if (!this._ready) return
    [110, 220, 330, 440, 660, 880, 1100].forEach((f,i) =>
      setTimeout(() => this._beep(f, 0.15, 0.06, 'sine'), i * 80)
    )
  }

  // Glitch/transition - noise burst
  glitch() {
    if (!this._ready) return
    try {
      const ctx = this.ctx
      const buf = ctx.createBuffer(1, ctx.sampleRate * 0.2, ctx.sampleRate)
      const d   = buf.getChannelData(0)
      for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * 0.4
      const src = ctx.createBufferSource()
      const g   = ctx.createGain()
      const f   = ctx.createBiquadFilter()
      f.type = 'bandpass'; f.frequency.value = 2000; f.Q.value = 0.8
      src.buffer = buf
      src.connect(f); f.connect(g); g.connect(this.master)
      g.gain.setValueAtTime(0.4, ctx.currentTime)
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2)
      src.start()
    } catch(e) {}
  }

  // Character rain sound
  rain() {
    if (!this._ready) return
    this._beep(800 + Math.random() * 1200, 0.01, 0.015, 'square')
  }

  // Error
  err() {
    if (!this._ready) return
    [400, 300, 200, 150].forEach((f,i) =>
      setTimeout(() => this._beep(f, 0.12, 0.08, 'square'), i * 70)
    )
  }

  hover() {
    if (!this._ready) return
    this._beep(900, 0.04, 0.015, 'sine')
  }

  // The big initialize sound - like hermians.xyz
  initialize() {
    if (!this._ready) return
    this.glitch()
    setTimeout(() => {
      [80, 120, 180, 240].forEach((f,i) =>
        setTimeout(() => this._beep(f, 0.3, 0.06, 'sawtooth'), i * 50)
      )
    }, 150)
    setTimeout(() => this.boot(), 500)
  }
}

export const SFX = new AudioEngine()
